package v1alpha1

import (
	corev1 "k8s.io/api/core/v1"
	apiextensionsv1 "k8s.io/apiextensions-apiserver/pkg/apis/apiextensions/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
)

// Well-known labels applied to every object generated by the platform operators.
const (
	LabelTenant      = "platform.mycompany.io/tenant"
	LabelEnvironment = "platform.mycompany.io/environment"
	LabelManagedBy   = "platform.mycompany.io/managed-by"

	// ManagedByValue is the value of LabelManagedBy for objects owned by this operator.
	ManagedByValue = "workload-operator"

	// WorkloadLabel selects the pods of one Workload.
	WorkloadLabel = "platform.mycompany.io/workload"
)

// Condition types reported on Workload.status.conditions.
const (
	ConditionReady           = "Ready"
	ConditionDeploymentReady = "DeploymentReady"
	ConditionTraitsApplied   = "TraitsApplied"
)

// Phase values for Workload.status.phase.
const (
	PhasePending     = "Pending"
	PhaseProgressing = "Progressing"
	PhaseReady       = "Ready"
	PhaseFailed      = "Failed"
)

// TraitType names an optional capability attached to a Workload.
// +kubebuilder:validation:Enum=ingress;autoscaling;pdb
type TraitType string

const (
	TraitIngress       TraitType = "ingress"
	TraitAutoscaling   TraitType = "autoscaling"
	TraitPodDisruption TraitType = "pdb"
)

// Trait attaches an optional capability (ingress, autoscaling, pdb) to a Workload.
type Trait struct {
	// Type selects the trait implementation.
	Type TraitType `json:"type"`

	// Config is trait specific. Unknown fields are rejected by the controller.
	// +optional
	// +kubebuilder:pruning:PreserveUnknownFields
	// +kubebuilder:validation:Type=object
	Config *apiextensionsv1.JSON `json:"config,omitempty"`
}

// WorkloadSpec defines the desired state of a Workload.
type WorkloadSpec struct {
	// Image is the container image to run.
	// +kubebuilder:validation:MinLength=1
	Image string `json:"image"`

	// Replicas is the desired number of pods. Ignored (owned by the HPA) when the
	// autoscaling trait is present.
	// +optional
	// +kubebuilder:default=1
	// +kubebuilder:validation:Minimum=0
	Replicas *int32 `json:"replicas,omitempty"`

	// Port is the container port, also used as the Service port.
	// +kubebuilder:validation:Minimum=1
	// +kubebuilder:validation:Maximum=65535
	Port int32 `json:"port"`

	// Env is passed to the container.
	// +optional
	Env []corev1.EnvVar `json:"env,omitempty"`

	// Resources are the container resource requirements.
	// +optional
	Resources corev1.ResourceRequirements `json:"resources,omitempty"`

	// Traits are optional capabilities. Each type may appear at most once.
	// +optional
	// +listType=map
	// +listMapKey=type
	// +kubebuilder:validation:MaxItems=3
	Traits []Trait `json:"traits,omitempty"`
}

// WorkloadStatus defines the observed state of a Workload.
type WorkloadStatus struct {
	// Phase is one of Pending, Progressing, Ready or Failed.
	// +optional
	Phase string `json:"phase,omitempty"`

	// AvailableReplicas is copied from the Deployment.
	// +optional
	AvailableReplicas int32 `json:"availableReplicas,omitempty"`

	// URL is set when the ingress trait is present.
	// +optional
	URL string `json:"url,omitempty"`

	// ObservedGeneration is the .metadata.generation last reconciled.
	// +optional
	ObservedGeneration int64 `json:"observedGeneration,omitempty"`

	// Conditions follow the Kubernetes condition conventions.
	// +optional
	// +listType=map
	// +listMapKey=type
	Conditions []metav1.Condition `json:"conditions,omitempty"`
}

// +kubebuilder:object:root=true
// +kubebuilder:subresource:status
// +kubebuilder:resource:scope=Namespaced,shortName=wl
// +kubebuilder:printcolumn:name="Image",type=string,JSONPath=`.spec.image`
// +kubebuilder:printcolumn:name="Phase",type=string,JSONPath=`.status.phase`
// +kubebuilder:printcolumn:name="Available",type=integer,JSONPath=`.status.availableReplicas`
// +kubebuilder:printcolumn:name="URL",type=string,JSONPath=`.status.url`
// +kubebuilder:printcolumn:name="Age",type=date,JSONPath=`.metadata.creationTimestamp`

// Workload describes a long-running service to run in its namespace.
type Workload struct {
	metav1.TypeMeta   `json:",inline"`
	metav1.ObjectMeta `json:"metadata,omitempty"`

	Spec   WorkloadSpec   `json:"spec,omitempty"`
	Status WorkloadStatus `json:"status,omitempty"`
}

// +kubebuilder:object:root=true

// WorkloadList contains a list of Workload.
type WorkloadList struct {
	metav1.TypeMeta `json:",inline"`
	metav1.ListMeta `json:"metadata,omitempty"`
	Items           []Workload `json:"items"`
}

func init() {
	SchemeBuilder.Register(&Workload{}, &WorkloadList{})
}
